Vec3 car_color(u32 i) {
  static const Vec3 c[] = {{0.62, 0.05, 0.04}, {0.08, 0.16, 0.42}, {0.85, 0.85, 0.86}, {0.06, 0.06, 0.07}, {0.45, 0.47, 0.5},
                           {0.12, 0.32, 0.18}, {0.9, 0.62, 0.08}, {0.3, 0.5, 0.75}, {0.55, 0.36, 0.22}, {0.7, 0.7, 0.66}};
  return converted::at(c, converted::rem(i, (converted::quot(std::size_t{120}, std::size_t{12}))));
}
game::Actor vehicle_actor(const char* name, const RigidSpec& spec, Vec3 pos, f32 yaw_deg) {
  using namespace game;
  Actor a;
  a.name = name;
  a.transform.position = pos;
  a.transform.rotation = {0, 0, yaw_deg};
  BodyComponent b;
  b.motion = Motion::dynamic;
  b.mass = spec.mass.mass;
  b.center_of_mass = spec.mass.center;
  for (int i = 0; i < 6; ++i) converted::at(b.inertia, i) = converted::at(spec.mass.inertia, i);
  b.linear_damping = spec.linear_damping;
  b.angular_damping = spec.angular_damping;
  b.bullet = spec.bullet;
  b.allow_sleep = false;
  a.body = b;
  for (const ColliderSpec& c : spec.colliders) {
    ColliderComponent cc;
    switch (c.kind) {
      case physics::ShapeKind::box: cc.shape = ColliderShape::box; break;
      case physics::ShapeKind::sphere: cc.shape = ColliderShape::sphere; break;
      case physics::ShapeKind::capsule: cc.shape = ColliderShape::capsule; break;
      default: cc.shape = ColliderShape::hull; break;
    }
    cc.center = c.center;
    cc.rotation = quat_to_euler(c.rotation);
    cc.size = c.size;
    cc.radius = c.radius;
    cc.length = c.length;
    cc.points = c.points;
    cc.friction = c.friction;
    cc.restitution = c.restitution;
    cc.density = 100;
    a.colliders.push_back(cc);
  }
  return a;
}
std::string json_escape(const std::string& s) {
  std::string o;
  for (char c : s) {
    if (c == '"' || c == '\\') o += '\\';
    if (static_cast<unsigned char>(c) < 0x20) continue;
    o += c;
  }
  return o;
}
const char* mode_name(Mode m) {
  switch (m) {
    case Mode::foot: return "foot";
    case Mode::drone: return "drone";
    case Mode::car: return "car";
    case Mode::jet: return "jet";
    case Mode::parachute: return "parachute";
  }
  return "?";
}
